    vec3 com_velocity{0.0, 0.0, 0.0};
    for (size_t i = 0; i < masses.size(); ++i) {
        double sigma = std::sqrt(temperature / masses[i]);
        // generate three normal variates using Box-Muller
        double u1 = static_cast<double>(std::rand()) / RAND_MAX;
        double u2 = static_cast<double>(std::rand()) / RAND_MAX;
        double mag = std::sqrt(-2.0 * std::log(u1));
        double x = mag * std::cos(2.0 * M_PI * u2);
